import {seed,validate,uid,now,progress,remove} from './store.js';
const $=(s,root=document)=>root?.querySelector(s), $$=(s,root=document)=>[...root.querySelectorAll(s)];
const esc=(v='')=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='collaboratif.v1', SESSION='collaboratif.session';
let data, storageError=false;
try {const raw=localStorage.getItem(KEY);data=raw?validate(JSON.parse(raw)):seed();}catch{data=seed();storageError=true;}
let me='noe';try{me=localStorage.getItem('collaboratif.member')||data.members[0].id;}catch{}if(!data.members.some(x=>x.id===me))me=data.members[0].id;
let unlocked=false;try{unlocked=sessionStorage.getItem(SESSION)==='yes';}catch{}
let page='home',filter='',view='board',mine=false,labelFilter='',channel='general',thread='',tag='',quote='',reply='',selectedNote='',detail=null,search='',navOpen=false,attachments=[];
const nav=[['home','grid','Vue d’ensemble'],['projects','folder','Projets'],['tasks','check','Tâches'],['chat','chat','Discussions'],['posts','feed','Fil d’équipe'],['deals','briefcase','Affaires'],['notes','note','Notes']];
const stages=['prospect','devis','négociation','gagnée','perdue'], probs=[.1,.3,.6,1,0], priorities=['Aucune','Basse','Moyenne','Haute','Urgente'];
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',folder:'M3 7V4h6l3 3h9v13H3z',check:'M9 11l3 3L22 4 M21 12v8H3V3h13',chat:'M21 3H3v15h5v4l5-4h8z',feed:'M4 4h16v16H4z M8 8h8 M8 12h8 M8 16h4',briefcase:'M3 7h18v14H3z M8 7V3h8v4 M3 12h18 M10 12v3h4v-3',note:'M4 3h16v18H4z M8 7h8 M8 11h8 M8 15h5',arrow:'M5 12h14 M13 6l6 6-6 6',plus:'M12 5v14 M5 12h14',search:'M10.5 3a7.5 7.5 0 1 0 0 15 7.5 7.5 0 0 0 0-15 M16 16l5 5',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',bell:'M5 17h14l-2-4V8a5 5 0 0 0-10 0v5z M10 21h4',chevron:'M9 5l7 7-7 7',close:'M5 5l14 14 M5 19L19 5',send:'M3 3l19 9-19 9 4-9z M7 12h15',download:'M12 3v12 M7 10l5 5 5-5 M4 17v4h16v-4',upload:'M12 16V3 M7 8l5-5 5 5 M4 17v4h16v-4',logout:'M9 4H3v16h6 M9 12h12 M16 7l5 5-5 5',menu:'M3 6h18 M3 12h18 M3 18h18',image:'M3 3h18v18H3z M3 17l6-6 5 5 3-3 4 4 M15 7h1',heart:'M12 21S1 14 3 7c2-5 7-4 9 0 2-4 7-5 9 0 2 7-9 14-9 14',calendar:'M4 5h16v16H4z M8 2v6 M16 2v6 M4 10h16',sun:'M12 6a6 6 0 1 0 0 12 6 6 0 0 0 0-12 M12 1v2 M12 21v2 M1 12h2 M21 12h2',trash:'M4 6h16 M9 6V3h6v3 M6 6l1 15h10l1-15 M10 10v7 M14 10v7',link:'M10 13l4-4 M8 16l-2 2a4 4 0 0 1-6-6l5-5 M16 8l2-2a4 4 0 0 1 6 6l-5 5',spark:'M12 2l3 7 7 3-7 3-3 7-3-7-7-3 7-3z'};
const icon=(n)=>`<svg width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.grid}"/></svg>`;
const btn=(action,text,cls='',attrs='')=>`<button type="button" class="${cls}" data-action="${action}" ${attrs}>${text}</button>`;
const member=(id)=>data.members.find(x=>x.id===id)||{name:'Membre',color:'#e6e8e0'};
const safeColor=c=>/^#[0-9a-f]{6}$/i.test(c)?c:'#dce5d5';
const avatar=(id,small=false)=>`<span class="avatar ${small?'small':''}" style="background:${safeColor(member(id).color)}" title="${esc(member(id).name)}">${esc(member(id).name.slice(0,2).toUpperCase())}</span>`;
const date=d=>d?new Date(d+'T12:00:00').toLocaleDateString('fr-CH',{day:'numeric',month:'short'}):'Sans échéance';
const ago=d=>{const m=Math.max(0,Math.floor((Date.now()-new Date(d))/60000));return m<1?'À l’instant':m<60?`${m} min`:m<1440?`${Math.floor(m/60)} h`:new Date(d).toLocaleDateString('fr-CH',{day:'numeric',month:'short'});};
const money=n=>new Intl.NumberFormat('fr-CH',{style:'currency',currency:data.settings.currency||'EUR',maximumFractionDigits:0}).format(n||0);
function md(text){return esc(text).split(/(```[\s\S]*?```)/g).map(part=>part.startsWith('```')?`<pre><code>${part.slice(3,-3)}</code></pre>`:part.replace(/^### (.+)$/gm,'<h4>$1</h4>').replace(/^##? (.+)$/gm,'<h3>$1</h3>').replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>').replace(/`([^`]+)`/g,'<code>$1</code>').replace(/(^|\s)([@#][\p{L}\d_-]+)/gu,'$1<span class="mention">$2</span>').replace(/\n/g,'<br>')).join('');}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),3500);}
function save(){try{localStorage.setItem(KEY,JSON.stringify(data));return true;}catch{toast('Stockage plein ou indisponible. Exportez vos données avant de fermer.');return false;}}
function activity(id,body){data.activity.unshift({id:uid(),entity_id:id,body,actor:me,created_at:now()});data.activity=data.activity.slice(0,500);}
const empty=(text='Rien ici pour le moment.')=>`<div class="empty">${icon('spark')}<h3>${text}</h3><p>Les prochaines idées prennent vie ici.</p></div>`;
function login(){ $('#app').innerHTML=`<main class="login"><section class="login-story"><a class="brand" href="/">${icon('grid')} collaboratif<span class="brand-dot">.</span></a><div><span class="eyebrow">LE BON ENDROIT POUR VOS IDÉES</span><h1>Les grandes choses<br>se construisent<br><em>ensemble.</em></h1><p>Moins d’outils éparpillés. Plus d’idées qui avancent.<br>Bienvenue dans votre espace de travail.</p></div><div class="login-art"><span></span><span></span><span></span><span></span><b>Faire place<br>au collectif.</b></div><small>UN ESPACE COMMUN. DES POSSIBILITÉS INFINIES.</small></section><section class="login-form"><div class="login-box"><span class="pill">Votre espace vous attend</span><h2>On s’y retrouve ?</h2><p>Entrez le code de votre espace pour commencer.</p><form id="login"><label>Code d’accès<input name="code" inputmode="numeric" type="password" autocomplete="off" maxlength="4" placeholder="• • • •" required autofocus></label><label>Votre profil<select name="member">${data.members.map(m=>`<option value="${esc(m.id)}">${esc(m.name)}</option>`).join('')}</select></label><p id="login-error" class="error" role="alert"></p><button class="primary">Entrer dans l’espace ${icon('arrow')}</button></form><p class="login-foot">Accès simplifié • Données conservées sur cet appareil</p></div></section></main>`; }
function go(p){page=p;filter='';search='';navOpen=false;thread='';detail=null;$('#overlay').innerHTML='';location.hash=p;render();}
function render(){if(!unlocked){login();return;} const title=nav.find(x=>x[0]===page)?.[2]||'Paramètres';
 $('#app').innerHTML=`<div class="shell ${navOpen?'nav-open':''}"><aside class="sidebar"><a class="brand" href="#home" data-go="home">${icon('grid')} collaboratif<span class="brand-dot">.</span></a><button class="workspace" data-action="settings"><span class="workspace-icon">S</span><span><b>${esc(data.settings.name)}</b><small>Espace de travail</small></span>${icon('chevron')}</button><span class="nav-caption">VOTRE ESPACE</span><nav>${nav.map(([id,i,name])=>`<button class="nav-item ${page===id?'active':''}" data-go="${id}">${icon(i)}<span>${name}</span>${id==='tasks'?`<small>${data.tasks.filter(t=>!t.parent_id&&data.statuses.find(s=>s.id===t.status_id)?.kind!=='done').length}</small>`:''}</button>`).join('')}</nav><div class="side-projects"><div class="nav-caption">PROJETS EN COURS ${btn('new-project','+','mini')}</div>${data.projects.slice(0,3).map(p=>`<button data-open="projects" data-id="${esc(p.id)}"><i style="background:${safeColor(p.color)}"></i>${esc(p.name)}</button>`).join('')}</div><div class="side-bottom"><div class="local-card"><span class="online-dot"></span><b>À votre rythme, ensemble.</b><p>Tout votre travail, au même endroit.</p>${btn('export',`Exporter l’espace ${icon('download')}`)}</div><button class="profile" data-action="settings">${avatar(me)}<span><b>${esc(member(me).name)}</b><small>Mon espace personnel</small></span>${icon('settings')}</button></div></aside><div class="main"><header class="topbar">${btn('nav',icon('menu'),'icon-btn mobile-only','aria-label="Ouvrir le menu"')}<div class="breadcrumb">Espace de travail <span>/</span><b>${esc(title)}</b></div><div class="top-actions"><button class="search-trigger" data-action="search">${icon('search')}<span>Rechercher</span><kbd>⌘ K</kbd></button>${btn('notifications',icon('bell'),'icon-btn','aria-label="Activité récente"')}${avatar(me,true)}</div></header><main class="content" id="content">${page==='home'?home():page==='tasks'?tasks():page==='projects'?projects():page==='chat'?chat():page==='posts'?posts():page==='deals'?deals():page==='notes'?notes():settings()}</main><footer class="app-footer"><span><i class="online-dot"></i> Enregistré sur cet appareil</span><span>Fait pour avancer ensemble.</span></footer></div></div>`;
 if(storageError){toast('La sauvegarde locale n’a pas pu être lue. Vous pouvez importer une sauvegarde.');storageError=false;}
 if(page==='chat')$('.messages')?.scrollTo(0,100000);
}
function heading(kicker,title,sub,action=''){return `<div class="page-heading"><div><span class="eyebrow">${kicker}</span><h1>${title}</h1><p>${sub}</p></div>${action}</div>`;}
function home(){const completed=data.tasks.filter(t=>data.statuses.find(s=>s.id===t.status_id)?.kind==='done').length;const active=data.projects.filter(p=>p.status==='en cours').length;const openDeals=data.deals.filter(d=>!['gagnée','perdue'].includes(d.stage));return `${heading('UN PEU DE CLARTÉ, BEAUCOUP D’ÉLAN',`Bonjour ${esc(member(me).name)} <span class="wave">✳</span>`,'Une nouvelle journée pour faire avancer les bonnes idées.',btn('new-task',`${icon('plus')} Créer une tâche`,'primary'))}<section class="welcome-banner"><div><span class="eyebrow">TOUT PART D’UNE BONNE ÉQUIPE</span><h2>Vos idées méritent<br>un espace pour grandir.</h2><p>Les projets, les échanges et les petites victoires.<br>Tout ce qui vous fait avancer, ensemble.</p><button class="text-link" data-go="projects">Explorer les projets ${icon('arrow')}</button></div><div class="banner-art" aria-hidden="true"><div class="orb orb-one"></div><div class="orb orb-two"></div><div class="orb orb-three"></div><div class="art-label">L’UNION FAIT L’IDÉE. <span>↗</span></div></div></section><section class="stats"><div class="stat">${icon('folder')}<span>Projets en cours</span><b>${active.toString().padStart(2,'0')}</b><small>Des idées qui prennent forme</small></div><div class="stat">${icon('check')}<span>Tâches terminées</span><b>${completed.toString().padStart(2,'0')}<em> / ${data.tasks.length}</em></b><small>Chaque étape compte</small></div><div class="stat">${icon('briefcase')}<span>Pipeline commercial</span><b>${money(openDeals.reduce((s,d)=>s+d.amount,0))}</b><small>${openDeals.length} opportunités à concrétiser</small></div><div class="stat">${icon('chat')}<span>Un collectif créatif</span><b>${data.members.length.toString().padStart(2,'0')}</b><small>Profils de démonstration inclus</small></div></section><div class="dashboard-grid"><section><div class="section-heading"><h2>Les projets du moment <span>${data.projects.length}</span></h2><button class="text-link" data-go="projects">Tout voir ${icon('arrow')}</button></div><div class="project-grid compact">${data.projects.slice(0,3).map(projectCard).join('')||empty()}</div><div class="section-heading"><h2>À garder dans le radar</h2><button class="text-link" data-go="tasks">Toutes les tâches ${icon('arrow')}</button></div><div class="panel task-list">${data.tasks.filter(t=>!t.parent_id&&data.statuses.find(s=>s.id===t.status_id)?.kind!=='done').slice(0,4).map(taskRow).join('')||empty('Tout est à jour !')}</div></section><aside class="dashboard-aside"><section class="panel activity-panel"><div class="section-heading"><h2>Dans l’espace</h2><span class="pill">Activité</span></div>${activityFeed().slice(0,4).join('')}<button class="text-link" data-go="posts">Ouvrir le fil d’équipe ${icon('arrow')}</button></section><section class="idea-card"><span>✳</span><h3>Une idée en tête ?</h3><p>Posez-la ici. Les meilleures idées commencent souvent par quelques mots.</p>${btn('new-note',`Prendre une note ${icon('arrow')}`,'text-link')}</section></aside></div>`;}
function projectCard(p){const pr=progress(data,p.id);return `<button class="project-card" data-open="projects" data-id="${esc(p.id)}"><div class="project-cover" style="background:${safeColor(p.color)}"><span>${icon('folder')}</span><div class="cover-shape"></div><span class="project-arrow">↗</span></div><div class="project-body"><span class="pill ${p.status==='terminé'?'green':''}">${esc(p.status)}</span><h3>${esc(p.name)}</h3><p>${esc(p.description.replace(/[#*]/g,'').split('\n')[0])}</p><div class="progress-label"><span>Avancement</span><b>${pr.pct}%</b></div><div class="progress"><i style="width:${pr.pct}%"></i></div><div class="project-bottom"><div>${avatar(p.lead,true)}<small>${pr.done}/${pr.total} tâches</small></div><small>${p.due_date?date(p.due_date):'À votre rythme'}</small></div></div></button>`;}
function projects(){const list=data.projects.filter(p=>p.name.toLowerCase().includes(filter.toLowerCase()));return `${heading('UNE VISION COMMUNE','Les projets prennent vie.','Du premier déclic à la dernière étape, gardez le cap.',btn('new-project',`${icon('plus')} Nouveau projet`,'primary'))}<div class="toolbar"><div class="tabs"><button class="selected">Tous les projets <span>${data.projects.length}</span></button></div><label class="filter-search">${icon('search')}<input data-filter placeholder="Rechercher un projet…" value="${esc(filter)}" aria-label="Rechercher un projet"></label></div><div class="project-grid">${list.map(projectCard).join('')||empty('Aucun projet trouvé.')}</div>`;}
function taskRow(t){const s=data.statuses.find(s=>s.id===t.status_id);return `<div class="task-row"><button class="task-check ${s?.kind==='done'?'checked':''}" data-action="toggle-task" data-id="${esc(t.id)}" aria-label="${s?.kind==='done'?'Rouvrir':'Terminer'} ${esc(t.title)}">${s?.kind==='done'?'✓':''}</button><button class="task-name" data-open="tasks" data-id="${esc(t.id)}"><small>COL-${t.num}</small><b>${esc(t.title)}</b></button><span class="task-project">${esc(data.projects.find(p=>p.id===t.project_id)?.name||'Sans projet')}</span><span class="pill task-status" style="--tag:${safeColor(s?.color)}">${esc(s?.name||'À faire')}</span>${avatar(t.assignee,true)}</div>`;}
function taskCard(t){const s=data.statuses.find(s=>s.id===t.status_id);return `<article class="kanban-card" draggable="true" data-drag-task="${esc(t.id)}"><div class="card-top"><small>COL-${t.num}</small>${btn('open-task','···','mini',`data-id="${esc(t.id)}" aria-label="Ouvrir la tâche"`)}</div><button class="card-title" data-open="tasks" data-id="${esc(t.id)}">${esc(t.title)}</button><div class="tags">${t.labels.map(id=>{const l=data.labels.find(x=>x.id===id);return l?`<span class="tag" style="--tag:${safeColor(l.color)}">${esc(l.name)}</span>`:'';}).join('')}</div><p class="card-project">${esc(data.projects.find(p=>p.id===t.project_id)?.name||'Sans projet')}</p><div class="card-bottom"><span class="priority p${t.priority}">${'▰'.repeat(Math.max(1,Math.min(t.priority,4)))} <small>${priorities[t.priority]}</small></span>${avatar(t.assignee,true)}</div><select class="card-move" data-task-status="${esc(t.id)}" aria-label="Statut de ${esc(t.title)}">${options(data.statuses,t.status_id)}</select></article>`;}
function tasks(){const list=data.tasks.filter(t=>!t.parent_id&&(!mine||t.assignee===me)&&(!labelFilter||t.labels.includes(labelFilter))&&t.title.toLowerCase().includes(filter.toLowerCase()));return `${heading('UN PAS APRÈS L’AUTRE','Place à l’action.','Les priorités sont claires. Le reste peut attendre.',`<div class="row">${btn('settings',icon('settings'),'secondary','aria-label="Personnaliser les tâches"')}${btn('new-task',`${icon('plus')} Nouvelle tâche`,'primary')}</div>`)}<div class="toolbar"><div class="tabs">${[['board','Kanban'],['list','Liste'],['project','Par projet']].map(([v,n])=>btn('view',n,view===v?'selected':'',`data-value="${v}"`)).join('')}</div><div class="row wrap"><label class="filter-search">${icon('search')}<input data-filter value="${esc(filter)}" placeholder="Rechercher…" aria-label="Rechercher une tâche"></label><select data-label-filter aria-label="Filtrer par étiquette"><option value="">Toutes les étiquettes</option>${options(data.labels,labelFilter)}</select>${btn('mine','Mes tâches',mine?'secondary selected':'secondary')}</div></div>${view==='board'?`<div class="kanban">${data.statuses.map(s=>`<section class="kanban-column" data-drop-status="${esc(s.id)}"><h3><i style="background:${safeColor(s.color)}"></i>${esc(s.name)}<span>${list.filter(t=>t.status_id===s.id).length}</span>${btn('new-task','+','mini',`data-status="${esc(s.id)}"`)}</h3>${list.filter(t=>t.status_id===s.id).map(taskCard).join('')}<button class="add-card" data-action="new-task" data-status="${esc(s.id)}">+ Ajouter une tâche</button></section>`).join('')}</div>`:view==='list'?`<div class="panel">${list.map(taskRow).join('')||empty('Aucune tâche pour ce filtre.')}</div>`:[...data.projects,{id:'',name:'Sans projet'}].map(p=>`<section class="group"><h3>${esc(p.name)}</h3><div class="panel">${list.filter(t=>t.project_id===p.id).map(taskRow).join('')||'<p class="muted inset">Aucune tâche.</p>'}</div></section>`).join('')}`;}
function activityFeed(id){return data.activity.filter(a=>!id||a.entity_id===id).slice(0,20).map(a=>`<div class="activity-item">${avatar(a.actor,true)}<div><p><b>${esc(member(a.actor).name)}</b> ${esc(a.body)}</p><small>${ago(a.created_at)}</small></div></div>`);}
function message(m,small=false){return `<article class="message ${small?'reply-message':''}">${avatar(m.author)}<div><div class="message-meta"><b>${esc(member(m.author).name)}</b><small>${ago(m.created_at)}</small></div><div class="rich">${md(m.body)}</div>${!small?btn('thread',`${icon('chat')} ${data.messages.filter(x=>x.parent_id===m.id).length||'Répondre'}`,'text-link',`data-id="${esc(m.id)}"`):''}</div></article>`;}
function chat(){const cur=data.channels.find(c=>c.id===channel)||data.channels[0];channel=cur?.id||'';const root=data.messages.find(m=>m.id===thread);const list=data.messages.filter(m=>m.channel_id===channel&&(thread?m.parent_id===thread:!m.parent_id));return `${heading('LE COLLECTIF, EN CONVERSATION','On en parle ici.','Les bonnes conversations font avancer les projets.',btn('new-channel',`${icon('plus')} Nouveau canal`,'secondary'))}<section class="chat-layout panel"><aside class="channels"><span class="nav-caption">LES CONVERSATIONS</span>${data.channels.map(c=>btn('channel',`<span>#</span> ${esc(c.name)}`,channel===c.id?'selected':'',`data-id="${esc(c.id)}"`)).join('')}</aside><div class="chat-main"><header class="chat-header"><div><h3># ${esc(cur?.name||'Nouveau canal')}</h3><small>${esc(cur?.description||'Créez un canal pour commencer.')}</small></div>${cur?.project_id?`<button class="secondary" data-open="projects" data-id="${esc(cur.project_id)}">Voir le projet ↗</button>`:''}</header>${thread?`<div class="thread-heading">${btn('close-thread','← Retour au canal','text-link')}<b>Réponses au fil</b></div>`:''}<div class="messages">${root&&thread?message(root,true):''}${list.map(m=>message(m,!!thread)).join('')||(!root?empty('Lancez la conversation.'): '<p class="muted inset">Soyez le premier à répondre.</p>')}</div>${cur?`<form id="message-form" class="chat-composer"><textarea name="body" required placeholder="${thread?'Répondre au fil…':`Message dans #${esc(cur.name)}…`}" aria-label="Message" maxlength="10000"></textarea><div class="composer-bottom"><span>@mentions · Markdown · ⌘ Entrée</span><button class="primary">Envoyer ${icon('send')}</button></div></form>`:''}</div></section>`;}
function linkCard(p){const item=data[p.link_type]?.find(x=>x.id===p.link_id);return item?`<button class="linked-card" data-open="${esc(p.link_type)}" data-id="${esc(item.id)}">${icon('link')} ${esc(item.title||item.name)} ${icon('arrow')}</button>`:'';}
function postCard(p,isReply=false){const cited=data.posts.find(x=>x.id===p.quote_id);return `<article class="panel post"><header>${avatar(p.author)}<div><b>${esc(member(p.author).name)}</b><small>${ago(p.created_at)}</small></div>${p.author===me?btn('delete-post',icon('trash'),'icon-btn',`data-id="${esc(p.id)}" aria-label="Supprimer le post"`):''}</header><div class="rich">${md(p.body)}</div>${p.images.length?`<div class="post-images">${p.images.map(src=>`<img src="${esc(src)}" alt="Image jointe au post">`).join('')}</div>`:''}${cited?`<blockquote><b>${esc(member(cited.author).name)}</b><p>${esc(cited.body)}</p></blockquote>`:''}${linkCard(p)}<footer>${btn('like',`${icon('heart')} ${p.likes.length||'J’aime'}`,p.likes.includes(me)?'liked':'',`data-id="${esc(p.id)}"`)}${!isReply?btn('reply-post',`${icon('chat')} ${data.posts.filter(x=>x.parent_id===p.id).length||'Répondre'}`,'',`data-id="${esc(p.id)}"`):''}${btn('quote-post','↻ Citer','',`data-id="${esc(p.id)}"`)}</footer>${reply===p.id?`<div class="post-replies">${data.posts.filter(x=>x.parent_id===p.id).map(r=>postCard(r,true)).join('')}<form id="post-reply" data-parent="${esc(p.id)}"><textarea name="body" required placeholder="Votre réponse…" aria-label="Votre réponse"></textarea><button class="primary">Répondre ${icon('send')}</button></form></div>`:''}</article>`;}
function posts(){const roots=data.posts.filter(p=>!p.parent_id);const tags=[...new Set(roots.flatMap(p=>p.body.match(/#[\p{L}\d_-]+/gu)||[]))];return `${heading('LES NOUVELLES DU COLLECTIF','Le fil des bonnes idées.','Partagez une avancée, une inspiration ou une petite victoire.')}<div class="feed-layout"><div class="feed-main"><form id="post-form" class="panel post-composer"><div class="row">${avatar(me)}<b>Quelque chose à partager ?</b></div>${quote?`<div class="quote-preview">Citation : ${esc(data.posts.find(p=>p.id===quote)?.body.slice(0,100))} ${btn('cancel-quote','×','mini')}</div>`:''}<textarea name="body" placeholder="Une idée, une nouvelle, une victoire… (@mention, #tag, Markdown)" aria-label="Nouveau post" maxlength="20000"></textarea><div class="attachment-preview">${attachments.map((src,i)=>`<div><img src="${esc(src)}" alt="Pièce jointe">${btn('remove-image','×','mini',`data-index="${i}"`)}</div>`).join('')}</div><div class="composer-bottom"><div class="row wrap"><label class="file-button" title="4 images maximum">${icon('image')}<span>Photos</span><input type="file" accept="image/png,image/jpeg,image/webp,image/gif" multiple id="post-images" hidden></label><select name="link" aria-label="Lier un élément"><option value="">Lier un élément…</option>${['tasks','projects','deals'].map(table=>`<optgroup label="${table==='tasks'?'Tâches':table==='projects'?'Projets':'Affaires'}">${data[table].map(x=>`<option value="${table}:${esc(x.id)}">${esc(x.title||x.name)}</option>`).join('')}</optgroup>`).join('')}</select></div><button class="primary">Publier ${icon('arrow')}</button></div></form><div class="tags filter-tags">${btn('tag','Tout',!tag?'selected':'', 'data-tag=""')}${tags.map(t=>btn('tag',esc(t),tag===t?'selected':'',`data-tag="${esc(t)}"`)).join('')}</div>${roots.filter(p=>!tag||p.body.includes(tag)).toReversed().map(p=>postCard(p)).join('')||empty('Votre première publication ?')}</div><aside><section class="panel team-card"><span class="eyebrow">UN ESPACE, PLUSIEURS TALENTS</span><h2>Le collectif</h2>${data.members.map(m=>`<div class="member-row">${avatar(m.id)}<span><b>${esc(m.name)}</b><small>${esc(m.role||'Membre')}</small></span>${m.id===me?'<span class="pill">Vous</span>':''}</div>`).join('')}<small class="muted">Profils locaux · aucun statut de présence en ligne</small></section><section class="idea-card"><h3>Les mots font des liens.</h3><p>Utilisez @ pour mentionner un profil et # pour retrouver les sujets.</p></section></aside></div>`;}
function deals(){const open=data.deals.filter(d=>!['gagnée','perdue'].includes(d.stage));return `${heading('LES RELATIONS QUI COMPTENT','Les prochaines opportunités.','Du premier échange à la signature, ne perdez jamais le fil.',btn('new-deal',`${icon('plus')} Nouvelle affaire`,'primary'))}<div class="stats three">${[['Pipeline',open.reduce((s,d)=>s+d.amount,0)],['Valeur pondérée',open.reduce((s,d)=>s+d.amount*probs[stages.indexOf(d.stage)],0)],['Affaires gagnées',data.deals.filter(d=>d.stage==='gagnée').reduce((s,d)=>s+d.amount,0)]].map(([t,v])=>`<div class="stat"><span>${t}</span><b>${money(v)}</b></div>`).join('')}</div><div class="kanban deals-board">${stages.map((s,i)=>{const list=data.deals.filter(d=>d.stage===s);return `<section class="kanban-column" data-drop-stage="${s}"><h3><i style="background:${['#929d9b','#c8a357','#a48ab4','#64876b','#ba7c70'][i]}"></i>${s}<span>${list.length}</span></h3><small class="column-total">${money(list.reduce((n,d)=>n+d.amount,0))}</small>${list.map(d=>`<article class="kanban-card" draggable="true" data-drag-deal="${esc(d.id)}"><small>${esc(d.client||'Nouveau client')}</small><button class="card-title" data-open="deals" data-id="${esc(d.id)}">${esc(d.name)}</button><h3>${money(d.amount)}</h3><p class="muted">${esc(d.next_action||'Définir la prochaine étape')}</p><div class="card-bottom"><small>${date(d.next_action_date)}</small>${avatar(d.owner,true)}</div><select data-deal-stage="${esc(d.id)}" class="card-move" aria-label="Étape de ${esc(d.name)}">${stages.map(x=>`<option ${x===d.stage?'selected':''}>${x}</option>`).join('')}</select></article>`).join('')}${btn('new-deal','+ Ajouter une affaire','add-card',`data-stage="${s}"`)}</section>`;}).join('')}</div>`;}
function notes(){const list=data.notes.filter(n=>(n.title+' '+n.body).toLowerCase().includes(filter.toLowerCase()));const n=data.notes.find(x=>x.id===selectedNote);return `${heading('UNE PLACE POUR CHAQUE IDÉE','Les pensées restent.','Capturez l’essentiel. Retrouvez-le au bon moment.',btn('new-note',`${icon('plus')} Nouvelle note`,'primary'))}<div class="notes-layout"><aside><label class="filter-search">${icon('search')}<input data-filter value="${esc(filter)}" placeholder="Rechercher une note…" aria-label="Rechercher une note"></label>${list.toSorted((a,b)=>b.updated_at.localeCompare(a.updated_at)).map(n=>`<button class="note-card ${n.id===selectedNote?'selected':''}" data-action="select-note" data-id="${esc(n.id)}">${icon('note')}<h3>${esc(n.title||'Sans titre')}</h3><p>${esc(n.body.slice(0,90))}</p><small>${ago(n.updated_at)}</small></button>`).join('')||empty('Aucune note trouvée.')}</aside><section class="panel note-editor">${n?`<div class="section-heading"><span class="pill">Note · Sauvegarde automatique</span><div class="row">${btn('preview-note','Aperçu','secondary')}${btn('delete-note',icon('trash'),'icon-btn',`data-id="${esc(n.id)}" aria-label="Supprimer la note"`)}</div></div><input class="note-title" data-note-title="${esc(n.id)}" value="${esc(n.title)}" aria-label="Titre de la note" placeholder="Sans titre"><textarea data-note-body="${esc(n.id)}" aria-label="Contenu de la note" placeholder="Laissez venir les idées…">${esc(n.body)}</textarea><div class="note-status">Markdown accepté · ${esc(member(n.author).name)} · <span id="note-saved">Enregistré</span></div>`:`<div class="note-empty"><span>✳</span><h2>Laissez de la place<br>à vos idées.</h2><p>Sélectionnez une note ou commencez une nouvelle page.</p>${btn('new-note','Créer une note','primary')}</div>`}</section></div>`;}
function options(items,value,blank){return (blank?'<option value="">'+esc(blank)+'</option>':'')+items.map(x=>`<option value="${esc(x.id)}" ${value===x.id?'selected':''}>${esc(x.name||x.title)}</option>`).join('');}
function field(name,label,value='',type='text',extra=''){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;}
function select(name,label,items,value,blank){return `<label>${label}<select name="${name}">${options(items,value,blank)}</select></label>`;}
function modal(title,body,wide=false){$('#overlay').innerHTML=`<div class="modal-backdrop"><section role="dialog" aria-modal="true" aria-label="${esc(title)}" class="modal ${wide?'wide':''}"><header><h2>${esc(title)}</h2>${btn('close',icon('close'),'icon-btn','aria-label="Fermer"')}</header><div class="modal-body">${body}</div></section></div>`;modal.previousFocus=document.activeElement;setTimeout(()=>$('input,textarea,button,select',$('.modal-body'))?.focus(),0);}
function close(){detail=null;$('#overlay').innerHTML='';modal.previousFocus?.focus?.();}
function create(table,preset={}){detail=null;const labels={tasks:'Nouvelle tâche',projects:'Nouveau projet',deals:'Nouvelle affaire',channels:'Nouveau canal',members:'Nouveau profil',statuses:'Nouveau statut',labels:'Nouvelle étiquette',fields:'Nouveau champ'};const nameKey=table==='tasks'?'title':'name';modal(labels[table],`<form id="create-form" data-table="${table}" data-preset="${esc(JSON.stringify(preset))}">${field(nameKey,table==='tasks'?'Titre':'Nom','','text','required maxlength="140"')}${table==='tasks'?select('project_id','Projet',data.projects,preset.project_id||'','Sans projet')+select('assignee','Responsable',data.members,me)+select('status_id','Statut',data.statuses,preset.status_id||data.statuses.find(s=>s.kind==='todo').id):''}${table==='projects'?'<p class="muted">Un canal de discussion sera créé avec le projet.</p>':''}${table==='deals'?field('client','Client')+field('amount','Montant',0,'number','min="0" step="0.01"'):''}${table==='channels'?field('description','Description')+select('project_id','Projet associé',data.projects,'','Aucun'):''}${table==='members'?field('role','Rôle'):''}${['statuses','labels'].includes(table)?field('color','Couleur','#748c69','color'):''}${table==='statuses'?`<label>Type<select name="kind"><option value="todo">À faire</option><option value="active" selected>En cours</option><option value="done">Terminé</option></select></label>`:''}${table==='fields'?`<label>Type<select name="type">${['text','number','date','select','checkbox'].map((t,i)=>`<option value="${t}">${['Texte','Nombre','Date','Liste','Case à cocher'][i]}</option>`).join('')}</select></label>${field('options','Options (séparées par des virgules)')}`:''}<div class="form-actions">${btn('close','Annuler','secondary')}<button class="primary">Créer ${icon('plus')}</button></div></form>`);}
function edit(table,id){const x=data[table]?.find(x=>x.id===id);if(!x){toast('Cet élément n’existe plus.');return;}detail={table,id};let body='';if(table==='tasks')body=`<span class="eyebrow">COL-${x.num}</span><form id="detail-form" data-table="tasks" data-id="${esc(id)}">${field('title','Titre',x.title,'text','required')}<div class="form-grid">${select('status_id','Statut',data.statuses,x.status_id)}<label>Priorité<select name="priority">${priorities.map((p,i)=>`<option value="${i}" ${i===x.priority?'selected':''}>${p}</option>`).join('')}</select></label>${select('assignee','Responsable',data.members,x.assignee,'Personne')}${field('due','Échéance',x.due,'date')}${select('project_id','Projet',data.projects,x.project_id,'Aucun')}${select('deal_id','Affaire',data.deals,x.deal_id,'Aucune')}</div><div class="label-options">${data.labels.map(l=>`<label class="check-label"><input type="checkbox" name="labels" value="${esc(l.id)}" ${x.labels.includes(l.id)?'checked':''}><span class="tag" style="--tag:${safeColor(l.color)}">${esc(l.name)}</span></label>`).join('')}</div>${data.fields.map(f=>f.type==='select'?`<label>${esc(f.name)}<select name="custom:${esc(f.id)}"><option value="">—</option>${f.options.map(o=>`<option ${x.fields[f.id]===o?'selected':''}>${esc(o)}</option>`).join('')}</select></label>`:f.type==='checkbox'?`<label class="check-label"><input type="checkbox" name="custom:${esc(f.id)}" ${x.fields[f.id]?'checked':''}>${esc(f.name)}</label>`:field(`custom:${f.id}`,esc(f.name),x.fields[f.id]||'',f.type)).join('')}<label>Description<textarea name="description" rows="4">${esc(x.description)}</textarea></label><div class="form-actions"><button class="primary">Enregistrer</button>${btn('delete-entity','Supprimer','danger',`data-table="tasks" data-id="${esc(id)}"`)}</div></form><section class="detail-section"><h3>Sous-tâches</h3>${data.tasks.filter(t=>t.parent_id===id).map(taskRow).join('')}${btn('new-subtask','+ Ajouter une sous-tâche','text-link',`data-id="${esc(id)}"`)}</section><section class="detail-section"><h3>Commentaires</h3>${data.comments.filter(c=>c.task_id===id).map(c=>`<div class="comment">${avatar(c.author,true)}<div><b>${esc(member(c.author).name)}</b><small> · ${ago(c.created_at)}</small><div class="rich">${md(c.body)}</div></div></div>`).join('')}<form id="comment-form" data-id="${esc(id)}"><textarea name="body" required placeholder="Un retour, une question…" aria-label="Commentaire"></textarea><button class="primary">Commenter</button></form></section>`;
 if(table==='projects'){const pr=progress(data,id);body=`<form id="detail-form" data-table="projects" data-id="${esc(id)}">${field('name','Nom du projet',x.name,'text','required')}<div class="progress-label"><span>${pr.done}/${pr.total} tâches terminées</span><b>${pr.pct}%</b></div><div class="progress"><i style="width:${pr.pct}%"></i></div><div class="form-grid"><label>Statut<select name="status">${['idée','en cours','en pause','terminé'].map(s=>`<option ${s===x.status?'selected':''}>${s}</option>`).join('')}</select></label>${select('lead','Responsable',data.members,x.lead,'Aucun')}${field('start_date','Début',x.start_date,'date')}${field('due_date','Échéance',x.due_date,'date')}${field('color','Couleur du projet',safeColor(x.color),'color')}</div><label>Description<textarea name="description">${esc(x.description)}</textarea></label><div class="form-actions"><button class="primary">Enregistrer</button>${btn('delete-entity','Supprimer','danger',`data-table="projects" data-id="${esc(id)}"`)}</div></form><section class="detail-section"><h3>Jalons</h3>${data.milestones.filter(m=>m.project_id===id).map(m=>`<div class="milestone"><input type="checkbox" data-milestone="${esc(m.id)}" ${m.done?'checked':''} aria-label="Terminer ${esc(m.title)}"><span>${esc(m.title)}</span><input type="date" data-milestone-date="${esc(m.id)}" value="${esc(m.due)}" aria-label="Date du jalon">${btn('delete-milestone','×','mini',`data-id="${esc(m.id)}"`)}</div>`).join('')}<form id="milestone-form" data-id="${esc(id)}" class="row">${field('title','Nouveau jalon','','text','required')}<button class="secondary">Ajouter</button></form></section><section class="detail-section"><div class="section-heading"><h3>Tâches du projet</h3>${btn('project-task','+ Ajouter','text-link',`data-id="${esc(id)}"`)}</div>${data.tasks.filter(t=>t.project_id===id&&!t.parent_id).map(taskRow).join('')}</section>${btn('project-channel',`${icon('chat')} Ouvrir le canal du projet`,'linked-card',`data-id="${esc(id)}"`)}`;}
 if(table==='deals')body=`<form id="detail-form" data-table="deals" data-id="${esc(id)}">${field('name','Nom de l’affaire',x.name,'text','required')}<div class="form-grid">${field('client','Client',x.client)}${field('amount','Montant',x.amount,'number','min="0" step="0.01"')}<label>Étape<select name="stage">${stages.map(s=>`<option ${s===x.stage?'selected':''}>${s}</option>`).join('')}</select></label>${select('owner','Responsable',data.members,x.owner,'Aucun')}</div><p class="muted">Valeur pondérée : ${money(x.amount*probs[stages.indexOf(x.stage)])}</p>${field('next_action','Prochaine action',x.next_action)}${field('next_action_date','Date de relance',x.next_action_date,'date')}<label>Description<textarea name="description">${esc(x.description)}</textarea></label><div class="form-actions"><button class="primary">Enregistrer</button>${btn('delete-entity','Supprimer','danger',`data-table="deals" data-id="${esc(id)}"`)}</div></form><section class="detail-section"><h3>Tâches associées</h3>${data.tasks.filter(t=>t.deal_id===id).map(taskRow).join('')}${btn('deal-task','+ Ajouter une tâche','text-link',`data-id="${esc(id)}"`)}</section>`;
 if(table==='notes'){selectedNote=id;go('notes');return;}
 const linked=data.posts.filter(p=>p.link_type===table&&p.link_id===id);if(linked.length)body+=`<section class="detail-section"><h3>Publications liées</h3>${linked.map(p=>postCard(p)).join('')}</section>`;
 body+=`<section class="detail-section"><h3>Historique</h3>${activityFeed(id).join('')||'<p class="muted">Les prochaines modifications apparaîtront ici.</p>'}</section>`;modal(table==='tasks'?'Détail de la tâche':table==='projects'?'Espace projet':'Détail de l’affaire',body,true);}
function settings(){return `${heading('UN ESPACE À VOTRE IMAGE','Les petits réglages.','Adaptez votre espace à votre façon de travailler.')}<div class="settings-grid"><section class="panel settings-panel"><h2>L’espace</h2><form id="settings-form">${field('name','Nom de l’espace',data.settings.name,'text','required')}<label>Devise<select name="currency"><option ${data.settings.currency==='EUR'?'selected':''}>EUR</option><option ${data.settings.currency==='CHF'?'selected':''}>CHF</option></select></label><button class="primary">Enregistrer</button></form><h3>Profils locaux</h3>${data.members.map(m=>`<div class="setting-row">${avatar(m.id,true)}<input data-setting-table="members" data-setting-id="${esc(m.id)}" data-setting-key="name" value="${esc(m.name)}" aria-label="Nom du profil">${btn('switch-member',m.id===me?'Vous':'Utiliser','secondary',`data-id="${esc(m.id)}"`)}</div>`).join('')}${btn('new-member','+ Ajouter un profil','text-link')}<p class="muted">Ces profils servent à organiser et attribuer le travail sur cet appareil.</p></section><section class="panel settings-panel"><h2>Votre méthode</h2><h3>Statuts des tâches</h3>${data.statuses.map((s,i)=>`<div class="setting-row"><input type="color" data-setting-table="statuses" data-setting-id="${esc(s.id)}" data-setting-key="color" value="${safeColor(s.color)}" aria-label="Couleur du statut"><input data-setting-table="statuses" data-setting-id="${esc(s.id)}" data-setting-key="name" value="${esc(s.name)}" aria-label="Nom du statut"><select data-setting-table="statuses" data-setting-id="${esc(s.id)}" data-setting-key="kind" aria-label="Type du statut">${['todo','active','done'].map((k,j)=>`<option value="${k}" ${s.kind===k?'selected':''}>${['À faire','En cours','Terminé'][j]}</option>`).join('')}</select>${btn('reorder','↑','mini',`data-table="statuses" data-id="${esc(s.id)}" data-direction="-1" aria-label="Monter"`)}${btn('reorder','↓','mini',`data-table="statuses" data-id="${esc(s.id)}" data-direction="1" aria-label="Descendre"`)}${btn('remove-setting','×','mini',`data-table="statuses" data-id="${esc(s.id)}" aria-label="Supprimer le statut"`)}</div>`).join('')}${btn('new-status','+ Ajouter un statut','text-link')}<h3>Étiquettes</h3>${data.labels.map(l=>`<div class="setting-row"><input type="color" data-setting-table="labels" data-setting-id="${esc(l.id)}" data-setting-key="color" value="${safeColor(l.color)}" aria-label="Couleur de l’étiquette"><input data-setting-table="labels" data-setting-id="${esc(l.id)}" data-setting-key="name" value="${esc(l.name)}" aria-label="Nom de l’étiquette">${btn('remove-setting','×','mini',`data-table="labels" data-id="${esc(l.id)}" aria-label="Supprimer l’étiquette"`)}</div>`).join('')}${btn('new-label','+ Ajouter une étiquette','text-link')}<h3>Champs personnalisés</h3>${data.fields.map(f=>`<div class="setting-row"><input data-setting-table="fields" data-setting-id="${esc(f.id)}" data-setting-key="name" value="${esc(f.name)}" aria-label="Nom du champ"><span class="pill">${esc(f.type)}</span>${btn('reorder','↑','mini',`data-table="fields" data-id="${esc(f.id)}" data-direction="-1" aria-label="Monter"`)}${btn('reorder','↓','mini',`data-table="fields" data-id="${esc(f.id)}" data-direction="1" aria-label="Descendre"`)}${btn('remove-setting','×','mini',`data-table="fields" data-id="${esc(f.id)}" aria-label="Supprimer le champ"`)}</div>${f.type==='select'?`<input data-setting-table="fields" data-setting-id="${esc(f.id)}" data-setting-key="options" value="${esc(f.options.join(', '))}" aria-label="Options du champ">`:''}`).join('')}${btn('new-field','+ Ajouter un champ','text-link')}</section><section class="panel settings-panel"><h2>Vos données, à portée de main.</h2><p>Votre travail est enregistré dans ce navigateur. Exportez une sauvegarde pour le transférer sur un autre appareil.</p><div class="row wrap">${btn('export',`${icon('download')} Exporter JSON`,'secondary')}<label class="secondary file-button">${icon('upload')} Importer JSON<input type="file" id="import-file" accept="application/json,.json" hidden></label></div><p class="muted">L’import remplace le contenu local après confirmation. Aucun serveur, compte ou service externe n’est utilisé.</p></section><section class="panel settings-panel"><h2>Accès simplifié</h2><p>Code d’accès : <b>1234</b>. Cette barrière locale sert à la démonstration ; elle ne constitue pas une authentification sécurisée.</p>${btn('logout',`${icon('logout')} Verrouiller l’espace`,'secondary')}<hr><h3>Notifications sur cet appareil</h3><p>Les notifications distantes nécessitent un backend. Vous pouvez tester une notification locale si votre navigateur le permet.</p>${btn('test-notification','Tester une notification locale','secondary')}</section></div>`;}
function newTask(values={}){const id=uid();data.tasks.push({id,num:Math.max(0,...data.tasks.map(t=>t.num))+1,title:'Nouvelle tâche',description:'',status_id:data.statuses.find(s=>s.kind==='todo').id,priority:2,assignee:me,due:'',project_id:'',deal_id:'',parent_id:'',labels:[],fields:{},author:me,created_at:now(),updated_at:now(),...values});return id;}
function refreshDetail(){const prev=detail;render();if(prev)edit(prev.table,prev.id);}
function exportData(){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`collaboratif-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);toast('Sauvegarde exportée.');}
function searchModal(q=''){search=q;const found=['tasks','projects','deals','notes','posts','messages'].flatMap(table=>data[table].filter(x=>(x.title||x.name||x.body||'').toLowerCase().includes(q.toLowerCase())).slice(0,6).map(x=>({table,x})));modal('Tout retrouver',`<label class="filter-search">${icon('search')}<input id="global-search" value="${esc(q)}" placeholder="Projet, tâche, note ou conversation…" aria-label="Recherche globale"></label><div id="search-results">${found.map(({table,x})=>`<button class="search-result" data-search-table="${table}" data-id="${esc(x.id)}"><small>${{tasks:'Tâche',projects:'Projet',deals:'Affaire',notes:'Note',posts:'Publication',messages:'Message'}[table]}</small><b>${esc((x.title||x.name||x.body).slice(0,140))}</b>${icon('arrow')}</button>`).join('')||empty('Aucun résultat.')}</div>`);}
// All actions use delegated events: no inline script or third-party library.
document.addEventListener('click',async e=>{const navEl=e.target.closest('[data-go]');if(navEl){e.preventDefault();go(navEl.dataset.go);return;}const opened=e.target.closest('[data-open]');if(opened){edit(opened.dataset.open,opened.dataset.id);return;}const result=e.target.closest('[data-search-table]');if(result){const {searchTable:table,id}=result.dataset;close();if(table==='posts'){reply=id;go('posts');}else if(table==='messages'){channel=data.messages.find(m=>m.id===id).channel_id;go('chat');}else edit(table,id);return;}
 const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id;
 if(a==='mention'){const area=el.closest('form').querySelector('textarea');const start=area.selectionStart,before=area.value.slice(0,start).replace(/@[\p{L}\d_-]*$/u,'@'+member(id).name.replace(/\s+/g,'-')+' ');area.value=before+area.value.slice(start);el.closest('.mention-suggestions').remove();area.focus();area.setSelectionRange(before.length,before.length);return;}
 if(a==='close'){close();return;}if(a==='nav'){navOpen=!navOpen;render();return;}if(a==='settings'){go('settings');return;}if(a==='new-task'){create('tasks',{status_id:el.dataset.status||data.statuses.find(s=>s.kind==='todo').id});return;}if(a==='new-project'){create('projects');return;}if(a==='new-deal'){create('deals',{stage:el.dataset.stage||'prospect'});return;}if(a==='new-channel'){create('channels');return;}if(a==='new-member'){create('members');return;}if(a==='new-status'){create('statuses');return;}if(a==='new-label'){create('labels');return;}if(a==='new-field'){create('fields');return;}
 if(a==='view'){view=el.dataset.value;render();return;}if(a==='mine'){mine=!mine;render();return;}if(a==='open-task'){edit('tasks',id);return;}
 if(a==='toggle-task'){const t=data.tasks.find(x=>x.id===id);t.status_id=data.statuses.find(s=>s.kind===(data.statuses.find(s=>s.id===t.status_id)?.kind==='done'?'todo':'done')).id;activity(id,`a mis à jour « ${t.title} »`);save();refreshDetail();return;}
 if(a==='new-subtask'||a==='project-task'||a==='deal-task'){create('tasks',a==='new-subtask'?{parent_id:id,project_id:data.tasks.find(t=>t.id===id).project_id}:a==='project-task'?{project_id:id}:{deal_id:id});return;}
 if(a==='project-channel'){let c=data.channels.find(c=>c.project_id===id);if(!c){const p=data.projects.find(p=>p.id===id);c={id:uid(),name:p.name.toLowerCase().replace(/\s+/g,'-'),description:'',project_id:id};data.channels.push(c);save();}channel=c.id;close();go('chat');return;}
 if(a==='channel'){channel=id;thread='';render();return;}if(a==='thread'){thread=id;render();return;}if(a==='close-thread'){thread='';render();return;}
 if(a==='tag'){tag=el.dataset.tag;render();return;}if(a==='like'){const p=data.posts.find(p=>p.id===id);p.likes=p.likes.includes(me)?p.likes.filter(x=>x!==me):[...p.likes,me];save();refreshDetail();return;}if(a==='reply-post'){reply=reply===id?'':id;refreshDetail();return;}if(a==='quote-post'){quote=id;close();go('posts');$('#post-form textarea').focus();return;}if(a==='cancel-quote'){quote='';render();return;}
 if(a==='remove-image'){attachments.splice(Number(el.dataset.index),1);const draft=$('#post-form textarea').value;render();$('#post-form textarea').value=draft;return;}
 if(a==='delete-post'){if(!confirm('Supprimer cette publication et ses réponses ?'))return;remove(data,'posts',id);save();refreshDetail();return;}
 if(a==='new-note'){const n={id:uid(),title:'Nouvelle note',body:'',author:me,updated_at:now()};data.notes.push(n);selectedNote=n.id;save();go('notes');return;}if(a==='select-note'){selectedNote=id;render();return;}if(a==='preview-note'){const n=data.notes.find(n=>n.id===selectedNote);modal(n.title,`<article class="rich">${md(n.body)}</article>`);return;}
 if(a==='delete-note'){if(!confirm('Supprimer cette note ?'))return;remove(data,'notes',id);selectedNote='';save();render();return;}
 if(a==='delete-entity'){if(!confirm(`Supprimer cet élément ? ${el.dataset.table==='projects'?'Ses tâches seront conservées sans projet.':''}`))return;remove(data,el.dataset.table,id);save();close();render();return;}
 if(a==='delete-milestone'){remove(data,'milestones',id);save();refreshDetail();return;}
 if(a==='remove-setting'){const t=el.dataset.table;if(t==='statuses'&&(data.tasks.some(x=>x.status_id===id)||['todo','done'].some(k=>data.statuses.find(s=>s.id===id)?.kind===k&&data.statuses.filter(s=>s.kind===k).length===1))){toast('Ce statut est utilisé ou nécessaire. Conservez au moins un statut À faire et Terminé.');return;}if(!confirm('Supprimer cet élément de configuration ?'))return;remove(data,t,id);save();render();return;}
 if(a==='reorder'){const list=data[el.dataset.table],index=list.findIndex(x=>x.id===id),target=index+Number(el.dataset.direction);if(target<0||target>=list.length)return;[list[index],list[target]]=[list[target],list[index]];save();render();return;}
 if(a==='switch-member'){me=id;try{localStorage.setItem('collaboratif.member',me);}catch{}render();toast(`Profil ${member(me).name} activé.`);return;}
 if(a==='export'){exportData();return;}if(a==='search'){searchModal();return;}if(a==='notifications'){modal('Dans l’espace',activityFeed().join('')||empty('Aucune activité récente.'));return;}
 if(a==='logout'){unlocked=false;try{sessionStorage.removeItem(SESSION);}catch{}close();render();return;}
 if(a==='test-notification'){if(!('Notification'in window)){toast('Ce navigateur ne prend pas en charge les notifications locales.');return;}try{const permission=await Notification.requestPermission();if(permission==='granted')new Notification('Collaboratif',{body:'Votre espace est prêt. Ceci est une notification locale.',icon:'/icon.svg'});else toast('Notifications non autorisées dans ce navigateur.');}catch{toast('Notifications indisponibles sur cet appareil.');}}
});
document.addEventListener('submit',e=>{const form=e.target;if(!(form instanceof HTMLFormElement))return;e.preventDefault();const f=new FormData(form),v=Object.fromEntries(f);if(form.id==='login'){if(v.code!=='1234'){$('#login-error').textContent='Ce code n’est pas le bon. Réessayez.';return;}unlocked=true;me=data.members.some(m=>m.id===v.member)?v.member:data.members[0].id;try{sessionStorage.setItem(SESSION,'yes');localStorage.setItem('collaboratif.member',me);}catch{}render();return;}
 if(form.id==='create-form'){const table=form.dataset.table,preset=JSON.parse(form.dataset.preset||'{}');const title=(v.title||v.name||'').trim();if(!title)return;let id=uid();if(table==='tasks')id=newTask({...preset,...v,title});else if(table==='projects'){data.projects.push({id,name:title,description:'',status:'idée',lead:me,start_date:'',due_date:'',color:'#e4edda',created_at:now()});data.channels.push({id:uid(),name:title.toLowerCase().replace(/\s+/g,'-'),description:'Les échanges du projet.',project_id:id});}else if(table==='deals'){data.deals.push({id,name:title,client:v.client||'',amount:Number(v.amount)||0,stage:preset.stage||'prospect',description:'',next_action:'',next_action_date:'',owner:me,created_at:now()});}else if(table==='channels'){data.channels.push({id,...v,name:title.toLowerCase().replace(/\s+/g,'-')});channel=id;}else if(table==='members')data.members.push({id,name:title,role:v.role,color:'#dce5d5'});else if(table==='statuses')data.statuses.push({id,name:title,kind:v.kind,color:v.color});else if(table==='labels')data.labels.push({id,name:title,color:v.color});else if(table==='fields')data.fields.push({id,name:title,type:v.type,options:v.options.split(',').map(s=>s.trim()).filter(Boolean)});activity(id,`a créé « ${title} »`);save();close();render();if(['tasks','projects','deals'].includes(table))edit(table,id);toast('Création enregistrée.');return;}
 if(form.id==='detail-form'){const {table,id}=form.dataset,x=data[table].find(x=>x.id===id);if(table==='tasks'){const custom={...x.fields};data.fields.forEach(field=>{const value=f.get(`custom:${field.id}`);custom[field.id]=field.type==='checkbox'?value==='on':field.type==='number'?(value===''?'':Number(value)):value||'';delete v[`custom:${field.id}`];});Object.assign(x,v,{priority:Number(v.priority),labels:f.getAll('labels'),fields:custom,updated_at:now()});}else Object.assign(x,v,table==='deals'?{amount:Number(v.amount)||0}:{});activity(id,`a mis à jour « ${x.title||x.name} »`);save();render();edit(table,id);toast('Modifications enregistrées.');return;}
 if(form.id==='message-form'){const body=v.body.trim();if(!body)return;data.messages.push({id:uid(),body,channel_id:channel,parent_id:thread,author:me,created_at:now()});activity(channel,'a envoyé un message');save();render();return;}
 if(form.id==='post-form'||form.id==='post-reply'){const body=(v.body||'').trim();if(!body&&!attachments.length)return;const [link_type='',link_id='']=(v.link||'').split(':');data.posts.push({id:uid(),body,images:form.id==='post-form'?[...attachments]:[],author:me,parent_id:form.dataset.parent||'',quote_id:form.id==='post-form'?quote:'',link_type,link_id,likes:[],created_at:now()});activity('posts','a partagé une publication');if(form.id==='post-form'){attachments=[];quote='';}save();refreshDetail();return;}
 if(form.id==='comment-form'){const body=v.body.trim();if(!body)return;data.comments.push({id:uid(),task_id:form.dataset.id,body,author:me,created_at:now()});activity(form.dataset.id,'a ajouté un commentaire');save();refreshDetail();return;}
 if(form.id==='milestone-form'){if(!v.title.trim())return;data.milestones.push({id:uid(),project_id:form.dataset.id,title:v.title.trim(),due:'',done:false});save();refreshDetail();return;}
 if(form.id==='settings-form'){data.settings={...data.settings,name:v.name.trim(),currency:v.currency};save();render();toast('Espace mis à jour.');}
});
document.addEventListener('input',e=>{const el=e.target;if(el.matches('textarea')&&el.closest('#message-form,#post-form,#post-reply,#comment-form')){const form=el.closest('form');form.querySelector('.mention-suggestions')?.remove();const q=/@([\p{L}\d_-]*)$/u.exec(el.value.slice(0,el.selectionStart));if(q){const matches=data.members.filter(m=>m.name.toLowerCase().replace(/\s+/g,'-').startsWith(q[1].toLowerCase())).slice(0,5);if(matches.length){const box=document.createElement('div');box.className='mention-suggestions';box.innerHTML=matches.map(m=>btn('mention',esc('@'+m.name),'',`data-id="${esc(m.id)}"`)).join('');el.before(box);}}}if(el.matches('[data-filter]')){const start=el.selectionStart;filter=el.value;render();const input=$('[data-filter]');input.focus();input.setSelectionRange(start,start);}if(el.id==='global-search'){const start=el.selectionStart;searchModal(el.value);$('#global-search').focus();$('#global-search').setSelectionRange(start,start);}if(el.dataset.noteTitle||el.dataset.noteBody){const n=data.notes.find(n=>n.id===(el.dataset.noteTitle||el.dataset.noteBody));n[el.dataset.noteTitle?'title':'body']=el.value;n.updated_at=now();const ok=save();$('#note-saved').textContent=ok?'Enregistré':'Non enregistré — exportez vos données';}});
document.addEventListener('change',async e=>{const el=e.target;if(el.dataset.taskStatus){const t=data.tasks.find(x=>x.id===el.dataset.taskStatus);t.status_id=el.value;activity(t.id,`a changé le statut de « ${t.title} »`);save();render();}if(el.dataset.dealStage){const d=data.deals.find(x=>x.id===el.dataset.dealStage);d.stage=el.value;activity(d.id,`a déplacé « ${d.name} » vers ${d.stage}`);save();render();}if(el.matches('[data-label-filter]')){labelFilter=el.value;render();}if(el.dataset.milestone){data.milestones.find(x=>x.id===el.dataset.milestone).done=el.checked;save();refreshDetail();}if(el.dataset.milestoneDate){data.milestones.find(x=>x.id===el.dataset.milestoneDate).due=el.value;save();}if(el.dataset.settingTable){const x=data[el.dataset.settingTable].find(x=>x.id===el.dataset.settingId);if(!el.value.trim()){toast('Ce champ ne peut pas être vide.');render();return;}if(el.dataset.settingKey==='kind'&&['todo','done'].includes(x.kind)&&data.statuses.filter(s=>s.kind===x.kind).length===1&&el.value!==x.kind){toast('Conservez au moins un statut À faire et Terminé.');render();return;}x[el.dataset.settingKey]=el.dataset.settingKey==='options'?el.value.split(',').map(x=>x.trim()).filter(Boolean):el.value;save();render();}
 if(el.id==='post-images'){const files=[...el.files].slice(0,4-attachments.length);for(const file of files){if(!['image/png','image/jpeg','image/webp','image/gif'].includes(file.type)){toast('Format accepté : PNG, JPEG, WebP ou GIF.');continue;}if(file.size>1500000){toast('Choisissez une image de moins de 1,5 Mo.');continue;}attachments.push(await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file);}));}const body=$('#post-form textarea').value,link=$('#post-form select').value;render();$('#post-form textarea').value=body;$('#post-form select').value=link;}
 if(el.id==='import-file'){const file=el.files[0];if(!file)return;try{if(file.size>15000000)throw Error('Fichier trop volumineux (15 Mo maximum).');const imported=validate(JSON.parse(await file.text()));if(!confirm('Remplacer toutes les données locales par cette sauvegarde ? Exportez d’abord vos données actuelles si nécessaire.'))return;const old=data;data=imported;if(!save()){data=old;return;}me=data.members[0].id;selectedNote='';channel=data.channels[0]?.id||'';render();toast('Sauvegarde importée.');}catch(err){toast('Import impossible : '+err.message);}el.value='';}
});
let dragged=null;
document.addEventListener('dragstart',e=>{const el=e.target.closest('[data-drag-task],[data-drag-deal]');if(!el)return;dragged={table:el.dataset.dragTask?'tasks':'deals',id:el.dataset.dragTask||el.dataset.dragDeal};e.dataTransfer.setData('text/plain',dragged.id);e.dataTransfer.effectAllowed='move';el.classList.add('dragging');});
document.addEventListener('dragover',e=>{const col=e.target.closest('[data-drop-status],[data-drop-stage]');if(col&&dragged){e.preventDefault();col.classList.add('drag-over');}});
document.addEventListener('dragleave',e=>e.target.closest('[data-drop-status],[data-drop-stage]')?.classList.remove('drag-over'));
document.addEventListener('dragend',()=>{dragged=null;$$('.drag-over,.dragging').forEach(e=>e.classList.remove('drag-over','dragging'));});
document.addEventListener('drop',e=>{const col=e.target.closest('[data-drop-status],[data-drop-stage]');if(!col||!dragged)return;e.preventDefault();const x=data[dragged.table].find(x=>x.id===dragged.id);if(dragged.table==='tasks'&&col.dataset.dropStatus)x.status_id=col.dataset.dropStatus;else if(dragged.table==='deals'&&col.dataset.dropStage)x.stage=col.dataset.dropStage;activity(x.id,`a déplacé « ${x.title||x.name} »`);save();dragged=null;render();});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'&&unlocked){e.preventDefault();searchModal();}if(e.key==='Escape'&&$('.modal'))close();if(e.key==='Enter'&&(e.metaKey||e.ctrlKey)&&e.target.closest('form')){e.preventDefault();e.target.closest('form').requestSubmit();}if(e.key==='Tab'&&$('.modal')){const els=$$('button,input,select,textarea,a[href]',$('.modal')).filter(e=>!e.disabled&&e.offsetParent!==null),first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue){try{data=validate(JSON.parse(e.newValue));if(!data.members.some(m=>m.id===me))me=data.members[0].id;render();if(detail)edit(detail.table,detail.id);toast('Espace mis à jour depuis un autre onglet.');}catch{toast('La modification externe n’a pas pu être chargée.');}}});
window.addEventListener('hashchange',()=>{const p=location.hash.slice(1);if([...nav.map(x=>x[0]),'settings'].includes(p)&&p!==page){page=p;close();render();}});
if([...nav.map(x=>x[0]),'settings'].includes(location.hash.slice(1)))page=location.hash.slice(1);
render();
